CREATE OR REPLACE FUNCTION halisia_private.reject_suspended_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF auth.uid() IS NOT NULL AND NOT public.halisia_account_active() THEN
  RAISE EXCEPTION 'Account app access is suspended' USING ERRCODE='42501';
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $function$
